import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"10、【履】 兑下乾上","description":"子夏易传 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"子夏易传 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/zixia/012.md","filePath":"zh/classics/zixia/012.md"}'),i={name:"zh/classics/zixia/012.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><p>卦辞：履，虎尾，不咥人，亨。</p><p>彖曰：履，柔履剛也。説而應乎乾，是以履虎尾不咥人，亨。剛中正，履帝位而不疚，光明也。</p><p>子夏：履，一隂而履於陽，為下之長，衆之趨焉。是以危而履虎尾也。語其上下，則下承上也。言其情，則説而奉於乾也。失其所履而全其所承，是以不咥人，亨。情之所歸，則三也。故以卦命之。其於履，則剛中正，履帝位而不疚。其義也能制其度，得其光明也。隂者陽之求，而履之陽不競者，以隂失位而凶陽，抑其情而不亂上之正，而咸得其履也。</p><p>象曰：上天下澤，履。君子以辨上，下定民志。</p><p>子夏：上天下澤得其履也。君子辨賢、不肖而上下定之，則民無覬倖之望也。</p><p>初九，素履，往，无咎。</p><p>象曰：素履之往，獨行願也。</p><p>子夏：履得其所履，吉也。過之則咎。以剛志而守下，不求其隂，進之不以為榮，獨履素，行之節是以，無過咎也。</p><p>九二，履道坦，坦幽人，貞吉。象曰；幽人，貞吉。中不自亂也。</p><p>子夏：履不得其履，寧倡無僣。二以剛比柔，見利，不撓其志。居易幽退，履其所履，中正之吉也。</p><p>六三，眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。</p><p>象曰：眇能視，不足以有明也。跛能履，不足以與行也。咥人之凶，位不當也。武人為于大君，志剛也。</p><p>子夏：卦皆無諸，隂而三，自以為己任。眇目能視，跛足能履，豈足恃哉。僣履非位，咥其冝也。而志擬於剛，欲為武人，大君之行凶之災也。</p><p>九四，履虎尾，愬愬，終吉。</p><p>象曰：愬愬終吉。志行也。</p><p>子夏：三以不順，為衆同棄而已，近也。愼於難履者也，心懼不足相與，在乎守卑以承於上，為上所任。果獲其志得其終，吉也。</p><p>九五，夬履，貞厲。</p><p>象曰：夬履，貞厲。位正當也。</p><p>子夏：三柔失位，志比武人，五為一卦之主，明得帝位取而決之，非求係於情也。然三者，衆之趨也。雖曰決之，正之危也。位正當也。何其患乎。</p><p>上九，視履考祥，其旋元吉。</p><p>象曰：元吉，在上大有慶也。</p><p>子夏：積善之家，必有餘慶。歸其本也。不顧其邪，自履其所得履之終也。則可以心視其往之履，而考其善應也。積其行，得其終，歸其有慶者矣。旋其元吉哉。</p>',23)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
